-- public.waive_request
begin;
create extension if not exists pgtap with schema extensions;
select * from no_plan();
create function pg_temp.n(q text) returns int language plpgsql as $f$ declare c int; begin execute q; get diagnostics c = row_count; return c; end $f$;
create function pg_temp.login(u uuid) returns void language plpgsql as $f$ begin
  perform set_config('request.jwt.claims', json_build_object('sub', u, 'role', 'authenticated')::text, true);
  perform set_config('role', 'authenticated', true); end $f$;
create function pg_temp.anon() returns void language plpgsql as $f$ begin
  perform set_config('request.jwt.claims', '{"role":"anon"}', true);
  perform set_config('role', 'anon', true); end $f$;

-- Events: e1 Team A absorb $45 (Ava, Ben, Teen); e2 Team A pass_on $25 (Ava); e3 club-issued $30 (Ava, Ben);
-- e4 Team A DRAFT; e5 Team B $20 (Cleo) on an account that cannot take charges yet.

reset role; select pg_temp.login('a2222222-2222-2222-2222-222222222222');
select throws_ok($$ select public.waive_request('b1000000-0000-0000-0000-000000000001', 'please') $$, '42501', 'not_authorized', 'a parent cannot waive their own request');
reset role; select pg_temp.login('a6666666-6666-6666-6666-666666666666');
select throws_ok($$ select public.waive_request('b1000000-0000-0000-0000-000000000001', 'x') $$, '42501', 'not_authorized', 'other teams'' staff cannot waive');
reset role; select pg_temp.login('a5555555-5555-5555-5555-555555555555');
select throws_ok($$ select public.waive_request('b1000000-0000-0000-0000-000000000001', 'x') $$, '42501', 'not_authorized', 'a club admin cannot waive a team-issued request');
reset role; select pg_temp.anon();
select throws_ok($$ select public.waive_request('b1000000-0000-0000-0000-000000000001', 'x') $$, '42501', null, 'anonymous cannot waive');
reset role; select pg_temp.login('a1111111-1111-1111-1111-111111111111');
select lives_ok($$ select public.waive_request('b1000000-0000-0000-0000-000000000001', 'Scholarship') $$, 'staff can waive an unpaid request');
select is((select status || ':' || note from public.payment_requests where id = 'b1000000-0000-0000-0000-000000000001'), 'waived:Scholarship', 'it is waived with the note');
select is((select waived_by::text from public.payment_requests where id = 'b1000000-0000-0000-0000-000000000001'), 'a1111111-1111-1111-1111-111111111111', 'who waived it is recorded');
select throws_ok($$ select public.waive_request('b1000000-0000-0000-0000-000000000001', 'again') $$, '23514', 'request_not_unpaid', 'a waived request cannot be waived again');
reset role;
update public.payment_requests set status = 'paid', paid_at = now() where id = 'b2000000-0000-0000-0000-000000000002';
update public.payment_requests set status = 'processing' where id = 'b3000000-0000-0000-0000-000000000003';
reset role; select pg_temp.login('a1111111-1111-1111-1111-111111111111');
select throws_ok($$ select public.waive_request('b2000000-0000-0000-0000-000000000002', 'x') $$, '23514', 'request_not_unpaid', 'a paid request cannot be waived');
select throws_ok($$ select public.waive_request('b3000000-0000-0000-0000-000000000003', 'x') $$, '23514', 'request_not_unpaid', 'one with a payment in flight cannot be waived');
select throws_ok($$ select public.waive_request('b5000000-0000-0000-0000-000000000005', 'x') $$, '42501', 'not_authorized', 'a coach cannot waive a club-issued request');
reset role;
select is((select count(*)::int from public.audit_log where action = 'payment_request.waive' and target_id = 'b1000000-0000-0000-0000-000000000001'), 1, 'the waive is audited');
select is((select (after ->> 'amount_cents')::int from public.audit_log where action = 'payment_request.waive' and target_id = 'b1000000-0000-0000-0000-000000000001'), 4500, 'with the amount waived');
reset role; select pg_temp.login('a2222222-2222-2222-2222-222222222222');
select throws_ok($$ select public.payer_checkout_quote(array['b1000000-0000-0000-0000-000000000001']::uuid[]) $$, '23514', 'request_not_payable', 'a waived request cannot be paid');

select * from finish();
rollback;
